  ClientSize=new Size(1280,860);PerformLayout();Application.DoEvents();check(ClientSize.Width==1280&&calendarView.Width>600,"compact default canvas fits a shorter window");consentMenu.PerformClick();Snapshot(Path.Combine(folder,"실시간_동의자.png"));nonConsentMenu.PerformClick();Snapshot(Path.Combine(folder,"실시간_비동의자.png"));
