   string key=y+"-"+nonConsent+"-"+scenario,now=Path.Combine(qa,key+".xlsx");var calculated=WorkbookBuilder.Calculate(settings);var exported=WorkbookBuilder.Build(now,settings);check(SameResult(calculated,exported),"memory and export totals agree "+key);
   if(baseline!=null){var oldType=baseline.GetType("SchoolWorkdayCalculator.Settings");object oldSettings=Activator.CreateInstance(oldType,true);foreach(var field in typeof(Settings).GetFields()){object value=field.GetValue(settings);if(value is DateRange){var range=(DateRange)value;value=Activator.CreateInstance(baseline.GetType("SchoolWorkdayCalculator.DateRange"),new object[]{range.Start,range.End,range.Name});}else if(field.Name=="Extras"){var extraType=baseline.GetType("SchoolWorkdayCalculator.ExtraHoliday");var list=(IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(extraType));foreach(var item in settings.Extras){var extra=Activator.CreateInstance(extraType,true);extraType.GetField("Date").SetValue(extra,item.Date);extraType.GetField("Name").SetValue(extra,item.Name);list.Add(extra);}value=list;}oldType.GetField(field.Name).SetValue(oldSettings,value);}
    string oldPath=Path.Combine(qa,key+"-old.xlsx");object oldResult=baseline.GetType("SchoolWorkdayCalculator.WorkbookBuilder").GetMethod("Build",BindingFlags.Static|BindingFlags.Public).Invoke(null,new[]{(object)oldPath,oldSettings});check(typeof(CalculationResult).GetFields().All(field=>(int)field.GetValue(calculated)==(int)oldResult.GetType().GetField(field.Name).GetValue(oldResult)),"counts match previous executable "+key);
    using(var newer=new OfficeOpenXml.ExcelPackage(new FileInfo(now)))using(var older=new OfficeOpenXml.ExcelPackage(new FileInfo(oldPath))){bool equal=true;foreach(var tab in newer.Workbook.Worksheets.Where(t=>t.Name!=WorkbookBuilder.PrescribedWorkdaySheet)){var prior=older.Workbook.Worksheets[tab.Name];foreach(var cell in tab.Cells.Where(c=>c.Start.Column<=40)){var oldCell=prior.Cells[cell.Address];if(cell.Formula!=oldCell.Formula||!Object.Equals(cell.Value,oldCell.Value))equal=false;}}check(equal,"all four calendars retain previous data and formulas "+key);}

   }
  }
